--
-- Table structure for table `ts_request_application_his`
--

DROP TABLE IF EXISTS `ts_request_application_his`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ts_request_application_his` (
  `id` int NOT NULL AUTO_INCREMENT,
  `request_id` int NOT NULL,
  `request_user_id` varchar(64) DEFAULT NULL,
  `request_product_name` varchar(200) DEFAULT NULL,
  `request_amount` int DEFAULT NULL,
  `estimate_price` decimal(19,2) DEFAULT NULL,
  `request_reason` varchar(50) DEFAULT NULL,
  `request_reason_detail` text,
  `expect_receive_date` datetime DEFAULT NULL,
  `description` text,
  `approver_user_id` varchar(64) DEFAULT NULL,
  `buyer_user_id` varchar(64) DEFAULT NULL,
  `approver_reject_reason` text,
  `buyer_reject_reason` text,
  `bought_product_name` varchar(200) DEFAULT NULL,
  `bought_price` decimal(19,2) DEFAULT NULL,
  `bought_place` text,
  `bought_amount` int DEFAULT NULL,
  `buyer_attachment` varchar(100) DEFAULT NULL,
  `request_user_attachment` varchar(100) DEFAULT NULL,
  `is_deleted` tinyint DEFAULT NULL,
  `status` varchar(20) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
